function InterventionModal({ teacher,student,data,setData,onClose,toast }) {
  const [message,setMessage]=useState("Mari ulangi materi dan latihan yang belum dikuasai. Jika masih kesulitan, temui Ibu setelah kelas."); const p=data.progress[student.id]||{completed:[],scores:{}}; const attempts=data.attempts.filter(a=>a.studentId===student.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  const send=()=>{setData(d=>({...d,notifications:[{id:uid("note"),userId:student.id,title:`Pesan dukungan dari ${teacher.name}`,body:message,read:false,createdAt:new Date().toISOString()},...d.notifications],interventions:[...d.interventions,{id:uid("help"),studentId:student.id,teacherId:teacher.id,message,createdAt:new Date().toISOString()}]}));toast("Pesan dukungan dikirim ke siswa.","success");onClose()};
  return <Modal title={`Tinjau ${student.name}`} onClose={onClose} wide><div className="student-review"><div className="review-stats"><div><span>Topik selesai</span><strong>{p.completed.length}</strong></div><div><span>Rata-rata percobaan</span><strong>{attempts.length?Math.round(attempts.reduce((sum,a)=>sum+a.score,0)/attempts.length):0}</strong></div><div><span>Total percobaan</span><strong>{attempts.length}</strong></div></div><h3>Riwayat asesmen</h3>{attempts.length?attempts.map(a=><div className="attempt-row" key={a.id}><div><strong>{data.materials.find(m=>m.id===a.materialId)?.title}</strong><span>{formatDate(a.createdAt)}</span></div><span className={`status ${a.score>=80?"good":"danger"}`}>{a.score}/100</span></div>):<p className="muted">Belum ada percobaan.</p>}<label>Pesan dukungan<textarea value={message} onChange={e=>setMessage(e.target.value)}/></label><div className="modal-actions"><Button kind="ghost" onClick={onClose}>Tutup</Button><Button onClick={send}>Kirim ke siswa <PaperPlaneTilt/></Button></div></div></Modal>;
}

function AdminApp({ data,setData,page,setPage,toast }) {
  if(page==="users") return <AdminUsers data={data} setData={setData} toast={toast}/>;
  if(page==="classes") return <AdminClasses data={data} setData={setData} toast={toast}/>;
  return <AdminSummary data={data}/>;
}

function AdminSummary({ data }) {
  return <div className="workspace-page dashboard-page"><div className="management-head"><div><span className="page-kicker">Administrasi Ruang Kode</span><h1>Kesiapan pembelajaran</h1><p>Ringkasan kurikulum dan asesmen kelas.</p></div></div><div className="teacher-stats"><div><span>Kelas aktif</span><strong>{data.classes.filter(item=>item.active!==false).length}</strong><small>Kelas terdaftar</small></div><div><span>Materi</span><strong>{data.materials.length}</strong><small>{data.materials.filter(item=>item.status==="published").length} diterbitkan</small></div><div><span>Bank soal</span><strong>{data.questions.length}</strong><small>Soal asesmen</small></div><div><span>Materi draf</span><strong>{data.materials.filter(item=>item.status==="draft").length}</strong><small>Menunggu penerbitan</small></div></div><div className="dashboard-grid"><section className="content-card"><div className="card-title"><div><h2>Materi terbaru</h2><p>Urut berdasarkan materi terakhir</p></div></div>{data.materials.slice(-4).reverse().map(material=><div className="activity-row" key={material.id}><div className="mini-icon sky"><BookOpen/></div><div><strong>{material.title}</strong><span>{material.category} · {material.competency}</span></div><span className={`status ${material.status==="published"?"good":"warning"}`}>{material.status==="published"?"Terbit":"Draf"}</span></div>)}</section><section className="content-card"><div className="card-title"><div><h2>Kesiapan asesmen</h2><p>Jumlah soal pada tiap materi</p></div></div>{data.materials.map(material=>{const count=data.questions.filter(question=>question.materialId===material.id).length;return <div className="activity-row readiness-row" key={material.id}><div><strong>{material.title}</strong><span>{material.category}</span></div><strong className="readiness-count">{count} soal</strong></div>})}</section></div></div>;
}

function AdminUsers({ data,setData,toast }) {
  const emptyForm={name:"",email:"",role:"student",classId:data.classes[0]?.id||"",identifier:"",password:""};
  const [open,setOpen]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState(emptyForm),[formError,setFormError]=useState("");
  const startCreate=()=>{setEditing(null);setForm(emptyForm);setFormError("");setOpen(true)};
  const startEdit=user=>{setEditing(user);setForm({name:user.name,email:user.email||"",role:user.role,classId:user.classId||data.classes[0]?.id||"",identifier:user.role==="student"?(user.nisn||user.loginId||""):user.role==="teacher"?(user.nip||user.loginId||""):(user.loginId||""),password:""});setFormError("");setOpen(true)};
  const closeForm=()=>{setOpen(false);setEditing(null);setFormError("")};
  const removeUser=user=>{if(!confirm(`Yakin ingin menghapus akun ${user.name}?`))return;setData(current=>({...current,users:current.users.filter(item=>item.id!==user.id),classes:current.classes.map(item=>({...item,studentIds:(item.studentIds||[]).filter(id=>id!==user.id),teacherId:item.teacherId===user.id?null:item.teacherId})),progress:Object.fromEntries(Object.entries(current.progress||{}).filter(([key])=>key!==user.id)),notifications:(current.notifications||[]).filter(note=>note.userId!==user.id),attempts:(current.attempts||[]).filter(attempt=>attempt.studentId!==user.id)}));toast("Pengguna dihapus.","success")};
  const save=async event=>{
    event.preventDefault();
    setFormError("");
    const email=form.role==="admin"?"":form.email.trim();
    const idError=numericIdError(form.identifier);
    if(idError){setFormError(idError);return}
    if(data.users.some(user=>user.id!==editing?.id&&[user.loginId,user.nisn,user.nip].filter(Boolean).some(value=>String(value).trim()===form.identifier.trim()))){setFormError("ID ini telah dipakai oleh pengguna lain. Gunakan ID yang berbeda.");return}
    if(form.role!=="admin"){
      if(!validEmail(email)){setFormError("Masukkan email dengan domain yang valid, misalnya nama@sekolah.sch.id.");return}
      if(data.users.some(user=>user.id!==editing?.id&&user.email?.trim().toLowerCase()===email.toLowerCase())){setFormError("Email ini sudah digunakan oleh pengguna lain.");return}
    }
    if(!editing||form.password){
      const error=passwordError(form.password);
      if(error){setFormError(error);return}
    }
    const id=editing?.id||uid("user"),passwordHash=form.password?await hashPassword(form.password):editing?.passwordHash;
    const existingFields={...(editing||{})};
    delete existingFields.nisn;
    delete existingFields.nip;
    const user={...existingFields,id,name:form.name.trim(),email,role:form.role,classId:form.role==="admin"?null:form.classId,loginId:form.identifier.trim(),active:editing?.active??true,...(form.role==="student"?{nisn:form.identifier.trim()}:{}),...(form.role==="teacher"?{nip:form.identifier.trim()}:{}),...(passwordHash?{passwordHash}:{})};
    setData(current=>{
      const users=editing?current.users.map(item=>item.id===id?user:item):[...current.users,user];
      const classes=current.classes.map(item=>({...item,studentIds:(item.studentIds||[]).filter(studentId=>studentId!==id),...(item.teacherId===id?{teacherId:null}:{})})).map(item=>{
        if(item.id!==user.classId)return item;
        if(user.role==="student")return {...item,studentIds:[...(item.studentIds||[]),id]};
        if(user.role==="teacher")return {...item,teacherId:id};
        return item;
      });
      const uniqueTeacherAssignment=classes.map(item=>user.role==="teacher"&&item.id!==user.classId&&item.teacherId===id?{...item,teacherId:null}:item);
      const synchronizedUsers=users.map(account=>account.role==="teacher"?{...account,classId:uniqueTeacherAssignment.find(item=>item.teacherId===account.id)?.id||null}:account);
      const progress=user.role==="student"&&!current.progress[id]?{...current.progress,[id]:{completed:[],practicePassed:[],scores:{},current:"html-structure"}}:current.progress;
      return {...current,users:synchronizedUsers,progress,classes:uniqueTeacherAssignment};
    });
    toast(editing?"Pengguna diperbarui.":"Pengguna ditambahkan.","success");
    closeForm();
  };
  const roleGroups=[["teacher","Guru"],["student","Murid"],["admin","Admin"]];
  return <div className="workspace-page"><div className="management-head"><div><span className="page-kicker">Administrasi Ruang Kode</span><h1>Pengguna</h1><p>Daftar akun berdasarkan peran.</p></div><Button onClick={startCreate}><Plus/> Tambah pengguna</Button></div>{roleGroups.map(([role,label])=>{const group=data.users.filter(user=>user.role===role);if(!group.length)return null;return <section className="content-card admin-role-group" key={role}><div className="card-title"><div><h2>{label}</h2><p>{group.length} akun</p></div></div><div className="attention-table"><table><thead><tr><th>No.</th><th>Nama</th><th>{role==="student"?"NISN":role==="teacher"?"NIP":"ID"}</th>{role!=="admin"&&<><th>Email</th><th>Kelas</th><th>Status</th></>}<th>Aksi</th></tr></thead><tbody>{group.map((user,index)=>{const identifier=role==="student"?(user.nisn||user.loginId||user.id):role==="teacher"?(user.nip||user.loginId||user.id):(user.loginId||user.id);return <tr key={user.id}><td>{String(index+1).padStart(2,"0")}</td><td><strong>{user.name}</strong></td><td>{identifier}</td>{role!=="admin"&&<><td>{user.email}</td><td>{data.classes.find(item=>item.id===user.classId)?.name||"—"}</td><td><span className={`status ${user.active?"good":"danger"}`}>{user.active?"Aktif":"Nonaktif"}</span></td></>}<td><div className="row-actions"><button className="row-action" onClick={()=>startEdit(user)}>Edit</button>{role!=="admin"&&<button className="row-action" onClick={()=>{setData(current=>({...current,users:current.users.map(item=>item.id===user.id?{...item,active:!item.active}:item)}));toast(`Akun ${user.active?"dinonaktifkan":"diaktifkan"}.`,"success")}}>{user.active?"Nonaktifkan":"Aktifkan"}</button>}<button className="row-action" onClick={()=>removeUser(user)}>Hapus</button></div></td></tr>})}</tbody></table></div></section>})}{open&&<Modal title={editing?"Edit pengguna":"Tambah pengguna"} onClose={closeForm}><form className="editor-form" onSubmit={save}><label><span>Nama lengkap <b className="req">*</b></span><input required value={form.name} onChange={event=>setForm(current=>({...current,name:event.target.value}))}/></label>{form.role!=="admin"&&<label><span>Email <b className="req">*</b></span><span className="field-hint">Gunakan format email dengan domain valid, misalnya nama@sekolah.sch.id.</span><input required type="email" value={form.email} onChange={event=>setForm(current=>({...current,email:event.target.value}))}/></label>}<label>Peran<select value={form.role} onChange={event=>setForm(current=>({...current,role:event.target.value,identifier:""}))}><option value="student">Murid</option><option value="teacher">Guru</option><option value="admin">Admin</option></select></label><label><span>{form.role==="student"?"NISN":form.role==="teacher"?"NIP":"ID admin"} <b className="req">*</b></span><span className="field-hint">Masukkan angka saja.</span><input required value={form.identifier} onChange={event=>setForm(current=>({...current,identifier:numericInputValue(event.target.value)}))} type="text" inputMode="numeric" pattern="[0-9]*"/></label>{form.role!=="admin"&&<label><span>Kelas <b className="req">*</b></span><select required value={form.classId} onChange={event=>setForm(current=>({...current,classId:event.target.value}))}>{data.classes.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}<label><span>Kata sandi <b className="req">*</b></span><span className="field-hint">{editing?"Kosongkan jika tidak ingin mengganti kata sandi. ":""}Minimal 6 karakter, mengandung huruf dan simbol.</span><input required={!editing} type="password" value={form.password} onChange={event=>setForm(current=>({...current,password:event.target.value}))}/></label>{formError&&<p className="form-error" role="alert">{formError}</p>}<div className="modal-actions"><Button type="button" kind="ghost" onClick={closeForm}>Batal</Button><Button type="submit">{editing?"Simpan perubahan":"Simpan pengguna"}</Button></div></form></Modal>}</div>;
}

function AdminClasses({ data,setData,toast }) {
  const emptyForm={name:"",teacherId:data.users.find(user=>user.role==="teacher")?.id||""};
  const [open,setOpen]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState(emptyForm),[formError,setFormError]=useState("");
  const startEdit=item=>{setEditing(item);setForm({name:item.name,teacherId:item.teacherId||""});setFormError("");setOpen(true)};
  const startCreate=()=>{setEditing(null);setForm(emptyForm);setFormError("");setOpen(true)};
  const closeForm=()=>{setOpen(false);setEditing(null);setFormError("")};
  const save=event=>{
    event.preventDefault();
    setFormError("");
    const name=form.name.trim();
    if(data.classes.some(item=>item.id!==editing?.id&&item.name.trim().toLowerCase()===name.toLowerCase())){setFormError("Nama kelas ini sudah digunakan.");return}
    const classId=editing?.id||uid("class");
    setData(current=>{
      const teacherId=form.teacherId||null;
      let classes=editing?current.classes.map(item=>item.id===classId?{...item,name,teacherId}:item):[...current.classes,{id:classId,name,teacherId,studentIds:[],active:true}];
      if(teacherId)classes=classes.map(item=>item.id!==classId&&item.teacherId===teacherId?{...item,teacherId:null}:item);
      const users=current.users.map(user=>user.role==="teacher"?{...user,classId:classes.find(item=>item.teacherId===user.id)?.id||null}:user);
      return {...current,classes,users};
    });
    toast(editing?"Kelas diperbarui.":"Kelas ditambahkan.","success");
    closeForm();
  };
  return <div className="workspace-page"><div className="management-head"><div><span className="page-kicker">Struktur sekolah</span><h1>Kelas</h1><p>Kelola kelas dan penanggung jawabnya.</p></div><Button onClick={startCreate}><Plus/> Tambah kelas</Button></div><div className="class-grid">{data.classes.map(item=><article key={item.id}><div className="mini-icon lilac"><Student weight="duotone"/></div><h2>{item.name}</h2><p>{data.users.filter(user=>user.classId===item.id&&user.role==="student").length} murid · {data.users.find(user=>user.id===item.teacherId)?.name||"Belum ada guru"}</p><span className={`status ${item.active===false?"danger":"good"}`}>{item.active===false?"Nonaktif":"Aktif"}</span><button className="row-action" onClick={()=>startEdit(item)}>Edit kelas</button></article>)}</div>{open&&<Modal title={editing?"Edit kelas":"Tambah kelas"} onClose={closeForm}><form className="editor-form" onSubmit={save}><label>Nama kelas<input required value={form.name} onChange={event=>setForm(current=>({...current,name:event.target.value}))} placeholder="Contoh: XI RPL B"/></label><label>Guru pengampu<select value={form.teacherId} onChange={event=>setForm(current=>({...current,teacherId:event.target.value}))}><option value="">Belum ditetapkan</option>{data.users.filter(user=>user.role==="teacher").map(user=><option key={user.id} value={user.id}>{user.name}</option>)}</select></label>{formError&&<p className="form-error" role="alert">{formError}</p>}<div className="modal-actions"><Button type="button" kind="ghost" onClick={closeForm}>Batal</Button><Button type="submit">{editing?"Simpan perubahan":"Simpan kelas"}</Button></div></form></Modal>}</div>;
}

function LegacyAdminApp({ data,setData,page,setPage,toast }) {
  const [open,setOpen]=useState(false),[form,setForm]=useState({name:"",email:"",role:"student",classId:"xi-rpl-a"});
  const save=async e=>{e.preventDefault();const id=uid("user"),passwordHash=await hashPassword(form.password||"");setData(d=>({...d,users:[...d.users,{...form,id,passwordHash,active:true}],classes:d.classes.map(c=>c.id===form.classId&&form.role==="student"?{...c,studentIds:[...c.studentIds,id]}:c)}));toast("Pengguna ditambahkan.","success");setOpen(false)};
  if(page==="classes") return <div className="workspace-page"><div className="management-head"><div><span className="page-kicker">Struktur sekolah</span><h1>Kelas</h1><p>Kelola kelas dan penanggung jawabnya.</p></div></div><div className="class-grid">{data.classes.map(c=><article key={c.id}><div className="mini-icon lilac"><Student weight="duotone"/></div><h2>{c.name}</h2><p>{data.users.filter(u=>u.classId===c.id&&u.role==="student").length} siswa · {data.users.find(u=>u.id===c.teacherId)?.name}</p><span className="status good">Aktif</span></article>)}</div></div>;
  const users=data.users;
  return <div className="workspace-page dashboard-page"><div className="management-head"><div><span className="page-kicker">Administrasi Ruang Kode</span><h1>{page==="users"?"Pengguna dan peran":"Kesiapan platform"}</h1><p>Kelola hak akses dan informasi pengguna.</p></div><Button onClick={()=>setOpen(true)}><Plus/> Tambah pengguna</Button></div><div className="teacher-stats"><div><span>Total pengguna</span><strong>{users.length}</strong><small>{users.filter(u=>u.role==="student").length} siswa · {users.filter(u=>u.role==="teacher").length} guru</small></div><div><span>Kelas aktif</span><strong>{data.classes.length}</strong><small>Semester ganjil</small></div><div><span>Materi</span><strong>{data.materials.length}</strong><small>{data.materials.filter(m=>m.status==="published").length} diterbitkan</small></div><div><span>Status sistem</span><strong className="ready">Siap</strong><small>Data lokal aktif</small></div></div><section className="content-card attention-table"><div className="card-title"><div><h2>Pengguna</h2><p>Akun dan hak akses</p></div></div><table><thead><tr><th>Nama</th><th>Peran</th><th>Kelas</th><th>Status</th><th>Aksi</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><div className="person-cell"><span className="avatar small">{u.name.split(" ").map(x=>x[0]).join("").slice(0,2)}</span><div><strong>{u.name}</strong><small className="table-sub">{u.email}</small></div></div></td><td>{u.role}</td><td>{data.classes.find(c=>c.id===u.classId)?.name||"—"}</td><td><span className={`status ${u.active?"good":"danger"}`}>{u.active?"Aktif":"Nonaktif"}</span></td><td><button className="row-action" onClick={()=>{setData(d=>({...d,users:d.users.map(x=>x.id===u.id?{...x,active:!x.active}:x)}));toast(`Akun ${u.active?"dinonaktifkan":"diaktifkan"}.`,"success")}}>{u.active?"Nonaktifkan":"Aktifkan"}</button></td></tr>)}</tbody></table></section>{open&&<Modal title="Tambah pengguna" onClose={()=>setOpen(false)}><form className="editor-form" onSubmit={save}><label>Nama lengkap<input required value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))}/></label><label>Email<input required type="email" value={form.email} onChange={e=>setForm(f=>({...f,email:e.target.value}))}/></label><label>Peran<select value={form.role} onChange={e=>setForm(f=>({...f,role:e.target.value}))}><option value="student">Siswa</option><option value="teacher">Guru</option><option value="admin">Administrator</option></select></label><label>Kelas<select value={form.classId} onChange={e=>setForm(f=>({...f,classId:e.target.value}))}><option value="xi-rpl-a">XI RPL A</option></select></label><div className="modal-actions"><Button type="button" kind="ghost" onClick={()=>setOpen(false)}>Batal</Button><Button>Tambah pengguna</Button></div></form></Modal>}</div>;
}

function PreviewModal({ material,questions,onClose }) { return <Modal title="Pratinjau siswa" onClose={onClose} wide><div className="preview-material"><span className="module-tag">{material.category} · {material.duration} menit</span><h2>{material.title}</h2><p className="lead">{material.summary}</p><p>{material.content}</p><div className="preview-code"><code>{material.practice}</code></div><h3>{questions.length} pertanyaan asesmen</h3>{questions.map(q=><div className="preview-question" key={q.id}><strong>{q.prompt}</strong><span>Jawaban: {q.options[q.correct]}</span></div>)}<div className="modal-actions"><Button onClick={onClose}>Selesai meninjau</Button></div></div></Modal>; }
function Modal({ title,children,onClose,wide=false }) { return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className={`modal ${wide?"wide":""}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><span>Ruang Kode</span><h2>{title}</h2></div><button onClick={onClose} aria-label="Tutup"><X/></button></div>{children}</div></div>; }
function Empty({ icon:Icon,title,copy }) { return <div className="empty-state"><Icon weight="duotone"/><strong>{title}</strong><p>{copy}</p></div>; }

export function App() {
  const [data,setData]=useStore(); const [screen,setScreen]=useState("landing"); const [userId,setUserId]=useState(null); const [notice,setNotice]=useState(null);
  const user=data.users.find(u=>u.id===userId);
  const toast=(text,type="success")=>{setNotice({text,type});setTimeout(()=>setNotice(null),2800)};
  const login=u=>{setUserId(u.id);setScreen("app");toast(`Masuk sebagai ${u.name}.`)};
  const logout=()=>{if(!confirm("Yakin ingin keluar? Kode praktik yang belum disimpan akan hilang."))return;setUserId(null);setScreen("login")};
  const setAdminCredentials=(adminId,loginId,passwordHash)=>setData(current=>({...current,users:current.users.map(account=>account.id===adminId?{...account,loginId,passwordHash}:account)}));
  return <>{screen==="landing"?<Landing data={data} onLogin={()=>setScreen("login")}/>:screen==="login"?<Login data={data} onLogin={login} onBack={()=>setScreen("landing")} onSetAdminCredentials={setAdminCredentials}/>:user?<AppShell user={user} data={data} setData={setData} onLogout={logout} toast={toast}/>:<Login data={data} onLogin={login} onBack={()=>setScreen("landing")} onSetAdminCredentials={setAdminCredentials}/>} {notice&&<div className={`toast ${notice.type}`}><CheckCircle weight="fill"/>{notice.text}</div>}</>;
}
